import{_ as e,o as t,c as p,ac as a}from"./chunks/framework.B-3EzaJq.js";const m=JSON.parse('{"title":"中国共产党第十二届中央委员会第六次全体会议关于召开党的第十三次全国代表大会的决议","description":"","frontmatter":{"prev":{"text":"中共中央关于社会主义精神文明建设指导方针的决议","link":"./中共中央关于社会主义精神文明建设指导方针的决议"},"next":{"text":"中国共产党第十二届中央委员会第六次全体会议公报","link":"./中国共产党第十二届中央委员会第六次全体会议公报"}},"headers":[],"relativePath":"12/6/中国共产党第十二届中央委员会第六次全体会议关于召开党的第十三次全国代表大会的决议.md","filePath":"12/6/中国共产党第十二届中央委员会第六次全体会议关于召开党的第十三次全国代表大会的决议.md"}'),r={name:"12/6/中国共产党第十二届中央委员会第六次全体会议关于召开党的第十三次全国代表大会的决议.md"};function n(o,_,s,i,c,l){return t(),p("div",null,[..._[0]||(_[0]=[a('<h1 id="中国共产党第十二届中央委员会第六次全体会议关于召开党的第十三次全国代表大会的决议" tabindex="-1">中国共产党第十二届中央委员会第六次全体会议关于召开党的第十三次全国代表大会的决议 <a class="header-anchor" href="#中国共产党第十二届中央委员会第六次全体会议关于召开党的第十三次全国代表大会的决议" aria-label="Permalink to &quot;中国共产党第十二届中央委员会第六次全体会议关于召开党的第十三次全国代表大会的决议&quot;">​</a></h1><p><em>（中国共产党第十二届中央委员会第六次全体会议1986年9月28日通过）</em></p><p>  一、按照党章的规定，中国共产党第十三次全国代表大会于1987年10月在北京召开。</p><p>  二、党的第十三次全国代表大会的主要议程是：</p><p>  （1）听取和审查中央委员会的报告；</p><p>  （2）听取和审查中央顾问委员会、中央纪律检查委员会的报告；</p><p>  （3）选举中央委员会；</p><p>  （4）选举中央顾问委员会和中央纪律检查委员会。</p><p>  三、党的第十三次全国代表大会的代表名额为一千九百五十名。</p><p>  出席这次大会的代表，由各省、自治区、直辖市，中央直属机关、中央国家机关，解放军各总部、军兵种、大军区分别召开党的代表大会或代表会议，按照中央分配给各选举单位的名额和党章规定的选举办法产生。</p><p>  代表的构成要具有广泛性。少数民族党员和妇女党员应有适当比例。特别要注意选举一定数量在社会主义现代化建设和各项改革中成绩卓著的中青年党员。</p><p>  四、中央号召党的各级组织和全党同志，按照党的十二大精神和中央的部署，坚决站在伟大改革的前列，认真贯彻执行社会主义物质文明和精神文明一起抓的方针，团结全国各族人民，艰苦奋斗，更加努力地开创社会主义现代化建设的新局面，迎接党的第十三次全国代表大会的召开。</p>',12)])])}const f=e(r,[["render",n]]);export{m as __pageData,f as default};
